    "{agent}'s hook needs RTK 0.51 or newer: older ones install it only per project. Update RTK (brew upgrade rtk, or its installer again), then switch it on.": "{agent} 的 hook 需要 RTK 0.51 或更高版本：旧版只能按项目安装。请先更新 RTK（brew upgrade rtk，或重新运行其安装脚本）再打开。",
    "OpenCode 2 refuses to load this plugin: RTK before 0.52 writes it for OpenCode 1. Update RTK (brew upgrade rtk, or its installer again) and switch it on again, or switch this off.": "OpenCode 2 拒绝加载这个插件：RTK 0.52 之前的版本写的是 OpenCode 1 的插件。请更新 RTK（brew upgrade rtk，或重新运行其安装脚本）后重新打开，或关闭此开关。",
    "OpenCode 2 needs RTK 0.52 or newer: older ones write a plugin for OpenCode 1, which OpenCode 2 refuses to load. Update RTK (brew upgrade rtk, or its installer again), then switch it on.": "OpenCode 2 需要 RTK 0.52 或更高版本：旧版写的是 OpenCode 1 的插件，OpenCode 2 拒绝加载。请先更新 RTK（brew upgrade rtk，或重新运行其安装脚本）再打开。",
    "No RTK hook": "RTK 暂不支持",
