    "{agent} reads Claude Code's CLAUDE.md when it has no AGENTS.md of its own.": "{agent} 在没有自己的 AGENTS.md 时会读取 Claude Code 的 CLAUDE.md。",
    "This file is {agent}'s profile of you: magpie adds its part after yours and leaves your own lines in it. A USER.md in a workspace is read instead of this one.": "该文件是 {agent} 对你的个人资料：magpie 会把它的部分加在你的内容之后，你自己的内容保留在文件里。工作区中的 USER.md 会代替此文件被读取。",
    "Antigravity reads Gemini CLI's ~/.gemini/GEMINI.md as well as this file, so text given to both is read twice.": "Antigravity 除此文件外还会读取 Gemini CLI 的 ~/.gemini/GEMINI.md，两边都写的内容会读两遍。",
