    "{agent} can't read {ref} from its settings — given this server, the token would be written there as plain text": "{agent} 无法从设置中读取 {ref} — 给它这个服务器，令牌就会以明文写进它的设置",
    "A value can name a variable, as {ref}: each agent is given it in its own way, so the token stays out of its settings": "值可以引用环境变量，写作 {ref}：每个智能体按自己的语法读取它，令牌不会写进它的设置",
    "{names} not set": "{names} 未设置",
    "magpie can't check it: {names} isn't set where magpie runs. An agent started where it is set still gets it": "magpie 无法检查：magpie 运行的环境里没有设置 {names}。在设置了它的环境中启动的智能体仍会拿到它",
    "{agent} runs only a command from its settings — add a remote server in its Connectors instead": "{agent} 的配置文件只支持命令启动的服务器 — 远程服务器请在它的「连接器」里添加",
    "Add a server once and switch it on for the agents that should have it — magpie writes it into each one's config in the shape that agent reads.": "服务器只需添加一次，再为需要的 Agent 开启，magpie 会按各 Agent 的格式写入其配置。",
