    "Copies are made again whenever the library's skill changes; edits made to them are replaced.": "资源库中的技能一有变化就会重新复制；对副本的修改会被覆盖。",
    "Links follow the library's skill: an update reaches the project at once.": "链接跟随资源库中的技能：更新会立即作用到项目。",
