    "Keeps a link to where it is: {agents} go on having it, and you can give it to the others": "保留指向原位置的链接：{agents} 继续拥有它，你也可以给其他 Agent",
    "Moves it into the library and links it back: {agents} go on having it, and you can give it to the others": "移入资源库并链接回去：{agents} 继续拥有它，你也可以给其他 Agent",
    "Keeps it where it is in the shared skills folder and links to it: you can give it to any agent": "保留在共享技能文件夹原处，资源库链接到它：可分配给任何 Agent",
    "Lists it in the library where it is, nothing moved: you can give it to any agent": "在原处列入资源库，不移动文件：可分配给任何 Agent",
    "{agent} reads ~/.agents/skills itself, where this skill is kept — it has it whatever is ticked here": "{agent} 会自行读取此技能所在的 ~/.agents/skills，无论是否勾选都能使用",
