    "{agent} reads no subagents magpie can write": "{agent} 沒有 magpie 能寫入的子代理",
    "{agents} can't bind MCP servers to a subagent: theirs gets its prompt, and every server the agent has.": "{agents} 不能給子代理單獨綁定 MCP 伺服器：它們拿到的子代理只有提示詞，可用該 Agent 的全部伺服器。",
    "{agents} can't bind skills to a subagent: theirs gets its prompt, and every skill the agent has.": "{agents} 不能給子代理單獨綁定技能：它們拿到的子代理只有提示詞，可用該 Agent 的全部技能。",
    "A subagent is a helper with a prompt of its own that an agent hands a task to — a reviewer, a test writer. Add it once and magpie writes it into each agent you pick, as that agent's own subagent file.": "子代理是有自己提示詞的助手，Agent 可以把任務交給它——例如審閱者、測試撰寫者。新增一次，magpie 就會把它寫進你選的每個 Agent，成為該 Agent 自己的子代理檔案。",
    "Add one, and pick the agents that can hand it a task.": "新增一個，並選擇可以把任務交給它的 Agent。",
    "e.g. code-reviewer": "例如 code-reviewer",
    "e.g. Reviews a diff for bugs. Use after code changes.": "例如：審閱 diff 裡的 bug。改完程式碼後使用。",
