    "Lowercase letters, digits and -; it is the file's name in each agent": "小寫字母、數字和 -；它也是每個 Agent 裡的檔名",
    "magpie can't give subagents to {agents} yet: their chips are greyed, and say why.": "magpie 還不能給 {agents} 寫入子代理：它們的圖示是灰的，懸停可看原因。",
    "magpie gives subagents only to agents on this computer, not yet to {agent} in WSL": "magpie 目前只給這台電腦上的 Agent 寫入子代理，還不支援 WSL 裡的 {agent}",
    "MCP servers: {names}": "MCP 伺服器：{names}",
    "New subagent": "新子代理",
    "No subagents in the library yet": "資源庫裡還沒有子代理",
    "Not bound for {agents}: theirs uses every server the agent has": "{agents} 不會綁定：其子代理可用該 Agent 的全部伺服器",
    "Not bound for {agents}: theirs uses every skill the agent has": "{agents} 不會綁定：其子代理可用該 Agent 的全部技能",
