    "Subagent {name}": "子代理 {name}",
    "The Cursor app has these subagents; its cursor-agent command reads only a project's own .cursor/agents.": "Cursor 應用程式會讀取這些子代理；它的 cursor-agent 命令只讀取專案自己的 .cursor/agents。",
