    "{agent} connects a server only once you trust it: switch it on in {agent}'s MCP settings, and again after its command or address changes.": "{agent} 只連線你信任過的伺服器：在 {agent} 的 MCP 設定裡開啟它一次，伺服器的指令或位址變更後要再開啟一次。",
