    "Copy {name} as an agent's project file has it, to paste into a project yourself": "按某個 agent 的專案設定檔格式複製 {name}，自己貼到專案裡",
    "Copy these servers as an agent's project file has them, to paste into a project yourself": "按某個 agent 的專案設定檔格式複製這些伺服器，自己貼到專案裡",
