    "{n} hooks removed": "已刪除 {n} 個 Hook",
    "A hook is a command an agent runs at a point of its turn — a notification when it ends, a formatter after it edits a file. Add it once and magpie writes it into each agent you pick, in the shape that agent reads.": "Hook 是 Agent 在一輪對話的某個時刻執行的命令——結束時發個通知，改完檔案後跑一下格式化。只需新增一次，magpie 會按每個 Agent 自己讀取的格式，寫進你選中的 Agent。",
    "Add one, and pick the agents that run it.": "新增一個，再選要執行它的 Agent。",
