    "{agents} has no skills folder.": "{agents} 沒有技能資料夾。",
    "Claude Desktop shows skill changes once its window is reloaded ({keys}). It gets a copy of each skill, and one you change in Desktop is left as it is.": "Claude Desktop 重新整理視窗（{keys}）後才顯示技能變化。它使用技能的副本，在 Desktop 中改過的副本不會被覆蓋。",
    "In projects": "專案中",
