    "Give a project's agents some of these skills as the project's own: magpie links them into its .claude/skills and .agents/skills and keeps them out of git.": "將部分技能作為專案技能提供給專案中的 Agent：連結到專案的 .claude/skills 和 .agents/skills，並讓 git 忽略。",
    "The project's folder, like ~/code/app": "專案資料夾，例如 ~/code/app",
    "{name} added — pick the skills it gets": "已新增 {name} — 選擇它要用的技能",
