    "{name} gets copies now": "{name} 現在使用副本",
    "{name} gets links now": "{name} 現在使用連結",
    "Copies are made again whenever the library's skill changes; edits made to them are replaced.": "資源庫中的技能一有變化就會重新複製；對副本的修改會被覆蓋。",
    "Links follow the library's skill: an update reaches the project at once.": "連結跟隨資源庫中的技能：更新會立即作用到專案。",
