    "{skill} is out of {name}": "{skill} 已從 {name} 移除",
    "Placed in {dirs} of the project and listed in its .gitignore. A folder there that isn't magpie's is left as it is.": "放在專案的 {dirs} 中並寫入其 .gitignore。其中非 magpie 放入的資料夾保持不動。",
    "{agents} reads no project skills folder magpie knows of.": "{agents} 沒有 magpie 已知的專案技能資料夾。",
    "The skills and MCP servers magpie put in it are taken away, with their lines in its .gitignore. Nothing else in the folder is touched.": "移除 magpie 放入的技能和 MCP 伺服器及其在 .gitignore 中的行，資料夾中其他內容不受影響。",
