    "Claude Code asks before it starts a project's servers; Codex reads .codex/config.toml, and Pi .pi/mcp.json, only in a project you trust.": "Claude Code 啟動專案伺服器前會先詢問；Codex 的 .codex/config.toml 和 Pi 的 .pi/mcp.json 僅在受信任的專案中讀取。",
