    "{agents} read ~/.agents/skills themselves: they have these {n} whatever is ticked here, and turning the group off for them leaves those on": "{agents} 會自行讀取 ~/.agents/skills：無論這裡是否勾選，這 {n} 個技能它們都能使用；為它們關閉此組時，這些仍保持可用",
