    "{agents} can't bind MCP servers to a subagent: theirs gets its prompt, and every server the agent has.": "{agents} はサブエージェントに MCP サーバーを個別に割り当てられません。サブエージェントにはプロンプトだけが渡り、エージェントのすべてのサーバーを使います。",
    "{agents} can't bind skills to a subagent: theirs gets its prompt, and every skill the agent has.": "{agents} はサブエージェントにスキルを個別に割り当てられません。サブエージェントにはプロンプトだけが渡り、エージェントのすべてのスキルを使います。",
    "A subagent is a helper with a prompt of its own that an agent hands a task to — a reviewer, a test writer. Add it once and magpie writes it into each agent you pick, as that agent's own subagent file.": "サブエージェントは、エージェントがタスクを任せる、独自のプロンプトを持つ助手です（レビュー役、テスト作成役など）。一度追加すれば、選んだ各エージェントに、そのエージェント自身のサブエージェントファイルとして magpie が書き込みます。",
    "Add one, and pick the agents that can hand it a task.": "追加して、タスクを任せられるエージェントを選んでください。",
    "e.g. code-reviewer": "例: code-reviewer",
    "e.g. Reviews a diff for bugs. Use after code changes.": "例: diff のバグをレビューする。コードを変更した後に使う。",
