    "magpie can't give subagents to {agents} yet: their chips are greyed, and say why.": "magpie はまだ {agents} にサブエージェントを渡せません。チップはグレーになっていて、理由を表示します。",
    "magpie gives subagents only to agents on this computer, not yet to {agent} in WSL": "magpie がサブエージェントを渡せるのはこのコンピューター上のエージェントだけで、WSL の {agent} にはまだ渡せません",
    "MCP servers: {names}": "MCP サーバー: {names}",
    "New subagent": "新しいサブエージェント",
