    "What it does and when to use it: the agent reads this to decide when to hand it a task": "何をするか、いつ使うか。エージェントはこれを読んで、いつタスクを任せるかを決めます",
    "What the subagent is told before its task": "サブエージェントがタスクの前に受け取る指示",
    "You are a careful code reviewer…": "あなたは注意深いコードレビュアーです…",
    "Give skills as": "スキルの渡し方",
    "The agents get copies of their skills now": "エージェントにはスキルのコピーを渡すようになりました",
    "The agents get links to their skills now": "エージェントにはスキルへのリンクを渡すようになりました",
    "By agent ({n})": "エージェント別（{n}）",
    "Give an agent its skills its own way": "エージェントごとに渡し方を決める",
    "Each agent gets a folder of its own, made again when the library's skill changes; edits made in a copy are replaced.": "各エージェントに独立したフォルダを渡し、ライブラリのスキルが変わると作り直します。コピーへの編集は上書きされます。",
    "Links follow the library's skill: an update reaches the agents at once.": "リンクはライブラリのスキルに従います。更新はすぐにエージェントに届きます。",
    "How each agent gets its skills": "エージェントごとのスキルの渡し方",
    "An agent can have its own way; the others get copies, as the library gives them.": "エージェントごとに決められます。ほかはライブラリの設定どおりコピーを受け取ります。",
    "An agent can have its own way; the others get links, as the library gives them.": "エージェントごとに決められます。ほかはライブラリの設定どおりリンクを受け取ります。",
