    "Gets copies": "コピーを受け取る",
    "Gets links": "リンクを受け取る",
    "Library's way": "ライブラリに従う",
    "{agent} gets copies of its skills now": "{agent} にはスキルのコピーを渡すようになりました",
    "{agent} gets links to its skills now": "{agent} にはスキルへのリンクを渡すようになりました",
    "Copy out of date": "コピーが古い",
    "The copy in {agents} differs from the library's skill. Click to copy it again.": "{agents} のコピーがライブラリのスキルと異なります。クリックしてコピーし直します。",
    "Copies updated": "コピーを更新しました",
    "Pick the agents that may generate images: each image costs what the model set in Settings → Images charges.": "画像を生成できるエージェントを選んでください：画像 1 枚ごとに、設定 → 画像 で選んだモデルの料金がかかります。",
    "For a server that asks you to sign in (OAuth): magpie signs in once, and every agent given it uses that sign-in": "サインインを求めるサーバー（OAuth）向け：magpie で一度サインインすれば、割り当てられたすべてのエージェントがそのサインインを使います",
