    "The agents given it use magpie's sign-in": "割り当てられたエージェントは magpie のサインインを使います",
    "{n} tools": "{n} 個のツール",
    "It started and listed its tools": "起動してツールを一覧表示しました",
    "The server asks for a sign-in — open it to sign in once in magpie": "サーバーがサインインを求めています。開いて magpie で一度サインインしてください",
    "The server asks for a sign-in": "サーバーがサインインを求めています",
