    "No answer in {n} seconds": "{n}秒以内に応答がありません",
    "no answer to {step}": "{step} に応答なし",
    "No answer to {step} in {n} seconds": "{step} に {n} 秒待っても応答がありません",
    "The server answered {status}": "サーバーが {status} を返しました",
    "Nothing is listening at that address": "そのアドレスで待ち受けているものがありません",
    "Can't reach the server": "サーバーに接続できません",
