    "{agent} connects a server only once you trust it: switch it on in {agent}'s MCP settings, and again after its command or address changes.": "{agent} は信頼したサーバーにだけ接続します。{agent} の MCP 設定で一度オンにしてください。サーバーのコマンドやアドレスが変わったら、もう一度オンにします。",
