    "A hook is a command an agent runs at a point of its turn — a notification when it ends, a formatter after it edits a file. Add it once and magpie writes it into each agent you pick, in the shape that agent reads.": "Ein Hook ist ein Befehl, den ein Agent an einem Punkt seines Durchgangs ausführt — eine Benachrichtigung, wenn er endet, ein Formatierer, nachdem er eine Datei bearbeitet hat. Einmal hinzugefügt, schreibt magpie ihn in jeden gewählten Agenten, in der Form, die dieser liest.",
