    "Copies are made again whenever the library's skill changes; edits made to them are replaced.": "Kopien werden neu erstellt, sobald sich der Skill der Bibliothek ändert; Änderungen daran werden ersetzt.",
    "Links follow the library's skill: an update reaches the project at once.": "Links folgen dem Skill der Bibliothek: Ein Update erreicht das Projekt sofort.",
    "Not placed": "Nicht abgelegt",
    "{skill} is in {name} for {agents}": "{skill} liegt in {name} für {agents}",
    "{skill} is out of {name}": "{skill} ist aus {name} entfernt",
    "Placed in {dirs} of the project and listed in its .gitignore. A folder there that isn't magpie's is left as it is.": "In {dirs} des Projekts abgelegt und in seiner .gitignore eingetragen. Ein Ordner dort, der nicht von magpie stammt, bleibt unverändert.",
    "{agents} reads no project skills folder magpie knows of.": "{agents} liest keinen Projekt-Skills-Ordner, den magpie kennt.",
    "The skills and MCP servers magpie put in it are taken away, with their lines in its .gitignore. Nothing else in the folder is touched.": "Die Skills und MCP-Server, die magpie dort abgelegt hat, werden entfernt, samt ihrer Zeilen in der .gitignore. Sonst wird im Ordner nichts angerührt.",
    "magpie forgets the project. The skills and MCP servers it put in the folder stay there as they are, with their lines in its .gitignore, and are yours from then on; a linked skill still follows the library's.": "magpie vergisst das Projekt. Die Skills und MCP-Server, die es im Ordner abgelegt hat, bleiben unverändert dort, samt ihrer Zeilen in der .gitignore, und gehören ab dann Ihnen; ein verlinkter Skill folgt weiterhin dem der Bibliothek.",
    "Keep its skills and MCP servers": "Skills und MCP-Server behalten",
    "Remove the project from magpie only, leaving what magpie wrote into it": "Projekt nur aus magpie entfernen; was magpie hineingeschrieben hat, bleibt erhalten",
    "{name} removed, its skills and servers kept": "{name} entfernt, Skills und Server behalten",
    "Give a project's agents some of these servers as the project's own: magpie writes them into its {files}, leaving the rest of each file as it is.": "Geben Sie den Agenten eines Projekts einige dieser Server als projekteigene: magpie schreibt sie in dessen {files} und lässt den Rest jeder Datei unverändert.",
    "{name} added — pick the servers it gets": "{name} hinzugefügt – wählen Sie seine Server",
    "No servers yet": "Noch keine Server",
    "Hide its servers": "Server ausblenden",
    "Pick the servers it gets": "Server wählen",
    "Not written": "Nicht geschrieben",
    "{server} is in {name} for {agents}": "{server} steht in {name} für {agents}",
    "{server} is out of {name}": "{server} ist aus {name} entfernt",
    "Written into {files} of the project, beside what's in them; a file magpie makes is listed in its .gitignore. A server there by the same name that isn't magpie's is left as it is.": "In {files} des Projekts geschrieben, neben dem vorhandenen Inhalt; eine von magpie erstellte Datei wird in seiner .gitignore eingetragen. Ein gleichnamiger Server dort, der nicht von magpie stammt, bleibt unverändert.",
    "Claude Code asks before it starts a project's servers; Codex reads .codex/config.toml, and Pi .pi/mcp.json, only in a project you trust.": "Claude Code fragt nach, bevor es die Server eines Projekts startet; Codex liest .codex/config.toml und Pi .pi/mcp.json nur in einem Projekt, dem Sie vertrauen.",
    "{agents} reads no project MCP file magpie knows of.": "{agents} liest keine Projekt-MCP-Datei, die magpie kennt.",
