    "You changed it since it was fetched from GitHub. Updating asks before it replaces your changes.": "Du hast ihn geändert, seit er von GitHub geholt wurde. Ein Update fragt, bevor es deine Änderungen ersetzt.",
    "Changed here: asks before it replaces your changes": "Hier geändert: fragt, bevor es deine Änderungen ersetzt",
    "Replace your changes to {name}?": "Deine Änderungen an {name} ersetzen?",
    "You changed {name} here since it was fetched from GitHub. Updating puts GitHub's version in its place. Yours is kept in magpie's backups (Backups, at the top of the Library).": "Du hast {name} hier geändert, seit er von GitHub geholt wurde. Das Update setzt die Version von GitHub an seine Stelle. Deine bleibt in den Backups von magpie (Backups, oben in der Bibliothek).",
