    "It is taken out of every agent it was given to. The folder it was linked from stays where it is.": "Er wird aus jedem Agenten entfernt, dem er gegeben wurde. Der Ordner, aus dem er verlinkt war, bleibt, wo er ist.",
    "It is taken out of every agent it was given to, and its folder is moved to magpie's backups.": "Er wird aus jedem Agenten entfernt, dem er gegeben wurde, und sein Ordner wird in die Backups von magpie verschoben.",
    "Its folder is moved to magpie's backups.": "Sein Ordner wird in die Backups von magpie verschoben.",
    "It is taken out of {agents}. The folder it was linked from stays where it is.": "Er wird aus {agents} entfernt. Der Ordner, auf den er verlinkt war, bleibt, wo er ist.",
    "It is taken out of {agents}, and its folder is moved to magpie's backups.": "Er wird aus {agents} entfernt, und sein Ordner wird in die Backups von magpie verschoben.",
    "Its entry in {path} goes to the backups too, so no agent reads it from there.": "Sein Eintrag in {path} kommt ebenfalls in die Backups, sodass kein Agent ihn mehr von dort liest.",
    "It is taken out of the MCP settings of {agents}. Each file is copied to magpie's backups before it changes.": "Er wird aus den MCP-Einstellungen von {agents} entfernt. Jede Datei wird vorher in die Backups von magpie kopiert.",
    "{agents} has another server by this name; that one stays.": "{agents} hat einen anderen Server mit diesem Namen; dieser bleibt.",
    "{agents} has another skill by this name; that one stays.": "{agents} hat einen anderen Skill mit diesem Namen; dieser bleibt.",
    "{agents} has another skill by this name; bringing this one in leaves that one as it is": "{agents} hat einen anderen Skill mit diesem Namen; das Übernehmen dieses Skills lässt jenen unverändert",
    "Keeps a link to where it is: {agents} go on having it, and you can give it to the others": "Behält einen Link auf seinen Ort: {agents} behalten ihn, und Sie können ihn den anderen geben",
    "Moves it into the library and links it back: {agents} go on having it, and you can give it to the others": "Verschiebt ihn in die Bibliothek und verlinkt ihn zurück: {agents} behalten ihn, und Sie können ihn den anderen geben",
    "Keeps it where it is in the shared skills folder and links to it: you can give it to any agent": "Belässt ihn im gemeinsamen Skills-Ordner und verlinkt darauf: Sie können ihn jedem Agenten geben",
    "Lists it in the library where it is, nothing moved: you can give it to any agent": "Nimmt ihn an Ort und Stelle in die Bibliothek auf, nichts wird verschoben: Sie können ihn jedem Agenten geben",
    "{agent} reads ~/.agents/skills itself, where this skill is kept — it has it whatever is ticked here": "{agent} liest ~/.agents/skills selbst, wo dieser Skill liegt – es hat ihn unabhängig davon, was hier angehakt ist",
