    "{agent} reads ~/.agents/skills itself, where all of these are kept — it has them whatever is ticked here": "{agent} liest ~/.agents/skills selbst, wo all diese liegen – es hat sie unabhängig davon, was hier angehakt ist",
    "It reads {n} of them from ~/.agents/skills itself: a click here leaves those as they are": "{n} davon liest es selbst aus ~/.agents/skills: ein Klick hier lässt diese, wie sie sind",
