    "1 result": "1 Ergebnis",
    "{n} results": "{n} Ergebnisse",
    "Featured, and the official MCP Registry": "Empfohlen und die offizielle MCP Registry",
    "Popular on skills.sh": "Beliebt auf skills.sh",
    "skills.sh's search didn't answer ({error}), so these are only the matches among magpie's picks and the most installed skills.": "Die Suche von skills.sh hat nicht geantwortet ({error}). Das hier sind nur die Treffer unter magpies Empfehlungen und den meistinstallierten Skills.",
    "The MCP Registry didn't answer ({error}), so these are only magpie's featured servers that match.": "Die MCP Registry hat nicht geantwortet ({error}). Das hier sind nur die passenden Server aus magpies Empfehlungen.",
