    "By agent": "Por agente",
    "Turn every skill on or off for one agent": "Activar o desactivar todas las habilidades para un agente",
    "Turn every server on or off for one agent": "Activar o desactivar todos los servidores para un agente",
    "Skills by agent": "Habilidades por agente",
