    "{n} hooks removed": "{n} hooks eliminados",
    "A hook is a command an agent runs at a point of its turn — a notification when it ends, a formatter after it edits a file. Add it once and magpie writes it into each agent you pick, in the shape that agent reads.": "Un hook es un comando que un agente ejecuta en determinado punto de su turno: una notificación cuando termina, un formateador después de editar un archivo. Agrégalo una vez y magpie lo escribirá en cada agente que elijas, en el formato que ese agente lee.",
    "Add one, and pick the agents that run it.": "Agrega uno y elige los agentes que lo ejecutan.",
    "After a tool runs": "Después de que se ejecuta una herramienta",
    "Before a tool runs": "Antes de que se ejecuta una herramienta",
    "Codex runs a new or changed hook only once you trust it: review it in Codex's /hooks.": "Codex solo ejecuta un hook nuevo o modificado una vez que confíes en él: revísalo en /hooks de Codex.",
    "Cursor runs Claude Code's hooks too: a hook given to both runs twice in Cursor.": "Cursor también ejecuta los hooks de Claude Code: un hook asignado a ambos se ejecuta dos veces en Cursor.",
    "e.g. notify": "ej. notify",
    "Each agent's own names for them": "Los nombres propios de cada agente para ellos",
    "Every agent has all of these hooks — click to take them from every one": "Todos los agentes tienen todos estos hooks — haz clic para quitárselos a todos",
