    "Add {n} servers": "Agregar {n} servidores",
    "Added {n} servers": "{n} servidores agregados",
    "A skill is a folder with a SKILL.md an agent loads when it's needed. The library keeps each one once and links it into the agents you pick.": "Una habilidad es una carpeta con un archivo SKILL.md que un agente carga cuando es necesario. La biblioteca conserva cada una una sola vez y la enlaza en los agentes que elijas.",
    "In the library": "En la biblioteca",
    "By source": "Por origen",
    "not in the library — bring one in to give it to the others": "no está en la biblioteca: importa una para asignarla a los demás",
    "{agents} has no skills folder.": "{agents} no tiene carpeta de habilidades.",
    "Claude Desktop shows skill changes once its window is reloaded ({keys}). It gets a copy of each skill, and one you change in Desktop is left as it is.": "Claude Desktop muestra los cambios de habilidades una vez que se recarga su ventana ({keys}). Recibe una copia de cada habilidad, y las que modifiques en Desktop se dejan como están.",
    "In projects": "En proyectos",
    "Add a project": "Agregar un proyecto",
    "Give a project's agents some of these skills as the project's own: magpie links them into its .claude/skills and .agents/skills and keeps them out of git.": "Asigna a los agentes de un proyecto algunas de estas habilidades como propias del proyecto: magpie las enlaza en sus .claude/skills y .agents/skills y las mantiene fuera de git.",
    "The project's folder, like ~/code/app": "La carpeta del proyecto, como ~/code/app",
    "{name} added — pick the skills it gets": "{name} agregado — elige las habilidades que recibe",
    "Folder is gone": "La carpeta ya no existe",
