    "Hide its skills": "Ocultar sus habilidades",
    "Pick the skills it gets": "Elegir las habilidades que recibe",
    "Copy files instead of linking": "Copiar archivos en lugar de enlazar",
    "{name} gets copies now": "{name} ahora recibe copias",
    "{name} gets links now": "{name} ahora recibe enlaces",
    "Copies are made again whenever the library's skill changes; edits made to them are replaced.": "Las copias se vuelven a generar cada vez que cambia la habilidad de la biblioteca; las ediciones realizadas en ellas se reemplazan.",
    "Links follow the library's skill: an update reaches the project at once.": "Los enlaces siguen la habilidad de la biblioteca: una actualización llega al proyecto de inmediato.",
    "Not placed": "No colocado",
    "{skill} is in {name} for {agents}": "{skill} está en {name} para {agents}",
    "{skill} is out of {name}": "{skill} se quitó de {name}",
    "Placed in {dirs} of the project and listed in its .gitignore. A folder there that isn't magpie's is left as it is.": "Colocado en {dirs} del proyecto e incluido en su .gitignore. Una carpeta allí que no sea de magpie se deja como está.",
    "{agents} reads no project skills folder magpie knows of.": "{agents} no lee ninguna carpeta de habilidades de proyecto que magpie conozca.",
    "The skills and MCP servers magpie put in it are taken away, with their lines in its .gitignore. Nothing else in the folder is touched.": "Las habilidades y servidores MCP que magpie colocó en él se quitan, junto con sus líneas en el .gitignore. No se modifica nada más en la carpeta.",
    "magpie forgets the project. The skills and MCP servers it put in the folder stay there as they are, with their lines in its .gitignore, and are yours from then on; a linked skill still follows the library's.": "magpie olvida el proyecto. Las habilidades y servidores MCP que colocó en la carpeta permanecen como están, con sus líneas en el .gitignore, y son tuyos a partir de ese momento; una habilidad enlazada sigue reflejando la de la biblioteca.",
    "Keep its skills and MCP servers": "Conservar sus habilidades y servidores MCP",
    "Remove the project from magpie only, leaving what magpie wrote into it": "Eliminar el proyecto solo de magpie, dejando lo que magpie escribió en él",
    "{name} removed, its skills and servers kept": "{name} eliminado, sus habilidades y servidores se conservaron",
    "Give a project's agents some of these servers as the project's own: magpie writes them into its {files}, leaving the rest of each file as it is.": "Asigna a los agentes de un proyecto algunos de estos servidores como propios del proyecto: magpie los escribe en sus {files}, dejando el resto de cada archivo como está.",
    "{name} added — pick the servers it gets": "{name} agregado — elige los servidores que recibe",
