    "Claude Code asks before it starts a project's servers; Codex reads .codex/config.toml, and Pi .pi/mcp.json, only in a project you trust.": "Claude Code pregunta antes de iniciar los servidores de un proyecto; Codex lee .codex/config.toml, y Pi .pi/mcp.json, solo en un proyecto en el que confíes.",
